 62	/** Which rooms are occupied on a given night, for the front desk (CSV). */
 63	public final class OccupancyReport {
 64	
 65	    private final Rooms rooms;
 66	    private final ReservationStore store;
 67	
 68	    public OccupancyReport(Rooms rooms, ReservationStore store) {
 69	        this.rooms = rooms;
 70	        this.store = store;
 71	    }
 72	
 73	    public String generate(LocalDate night) {
 74	        List<Reservation> occupying = new ArrayList<>();
 75	        for (Reservation reservation : store.all()) {
 76	            boolean coversNight = !reservation.checkIn().isAfter(night) && reservation.checkOut().isAfter(night);
 77	            if (reservation.isPaid() && coversNight) {
 78	                occupying.add(reservation);
 79	            }
 80	        }
 81	        occupying.sort(Comparator.comparingInt(Reservation::roomNumber));
 82	
 83	        StringBuilder csv = new StringBuilder();
 84	        csv.append("Pousada Maré Alta,occupancy,").append(night).append('\n');
 85	        csv.append("room,type,reservation,check_in,check_out\n");
 86	        for (Reservation reservation : occupying) {
 87	            Room room = rooms.find(reservation.roomNumber()).orElseThrow();
 88	            csv.append(room.number()).append(',')
 89	                    .append(room.type()).append(',')
 90	                    .append(reservation.id()).append(',')
 91	                    .append(reservation.checkIn()).append(',')
 92	                    .append(reservation.checkOut()).append('\n');
 93	        }
 94	        csv.append("total,").append(occupying.size()).append('/').append(rooms.all().size()).append('\n');
 95	        return csv.toString();
 96	    }
 97	}
